select s.customer_id, t.pct_product, t.add_to_cart_duration_sec from sessions s inner join (select session_id, round((100 * sum(case when page = '/product' then 1 else 0 end)) / count(*), 1) as pct_product, sum(case when event_type = 'add_to_cart' then duration_sec else 0 end) as add_to_cart_duration_sec from web_events group by session_id) t on s.id = t.session_id where t.pct_product >= 46 order by pct_product, customer_id desc;
